/** Resolve a `stock:` Shape string to its entry; anything else → undefined. */
export function stockShape(shape: string): StockSilhouette | undefined {
  if (!shape.startsWith("stock:")) return undefined;
  return STOCK_SHAPES[shape.slice(6)];
}
